### 4. Missing Regression & Minimal Unit Test Specification

#### Deficiency in Current Test Suite
`src-tauri/src/lib.rs:247–257` contains a dummy stub (`dummy_nsevent_check`) that only verifies symbol compilation without asserting modifier masking or key filtering logic.

#### Required Unit Test Specification
A pure, headless Rust unit test validating the modifier predicate logic without requiring an active AppKit display server:

```rust
// In src-tauri/src/browser/tests.rs or src-tauri/src/lib.rs tests module:

#[cfg(test)]
mod macos_key_predicate_tests {
    /// Pure helper function extracted from the NSEvent monitor for deterministic unit testing.
    fn is_strict_cmd_w(modifier_flags_raw: u64, key_char: &str) -> bool {
        const COMMAND_MASK: u64 = 1 << 20; // NSEventModifierFlagCommand
        const SHIFT_MASK: u64   = 1 << 17; // NSEventModifierFlagShift
        const CONTROL_MASK: u64 = 1 << 18; // NSEventModifierFlagControl
        const OPTION_MASK: u64  = 1 << 19; // NSEventModifierFlagOption
        const CAPS_LOCK: u64    = 1 << 16; // NSEventModifierFlagCapsLock

        let has_cmd = (modifier_flags_raw & COMMAND_MASK) != 0;
        let has_forbidden = (modifier_flags_raw & (SHIFT_MASK | CONTROL_MASK | OPTION_MASK)) != 0;
        let is_w = key_char.eq_ignore_ascii_case("w");

        has_cmd && !has_forbidden && is_w
    }

    #[test]
    fn test_strict_cmd_w_predicate_matrix() {
        const CMD: u64 = 1 << 20;
        const SHIFT: u64 = 1 << 17;
        const OPTION: u64 = 1 << 19;
        const CTRL: u64 = 1 << 18;
        const CAPS: u64 = 1 << 16;

        // Valid triggers
        assert!(is_strict_cmd_w(CMD, "w"), "Standard Cmd+W must pass");
        assert!(is_strict_cmd_w(CMD, "W"), "Uppercase Cmd+W must pass");
        assert!(is_strict_cmd_w(CMD | CAPS, "w"), "Cmd+W with CapsLock enabled must pass");

        // Forbidden modifier triggers
        assert!(!is_strict_cmd_w(CMD | SHIFT, "w"), "Cmd+Shift+W (Close Window) must NOT match");
        assert!(!is_strict_cmd_w(CMD | OPTION, "w"), "Cmd+Option+W must NOT match");
        assert!(!is_strict_cmd_w(CMD | CTRL, "w"), "Cmd+Ctrl+W must NOT match");
        assert!(!is_strict_cmd_w(CMD | SHIFT | OPTION, "w"), "Cmd+Shift+Option+W must NOT match");

        // Wrong characters
        assert!(!is_strict_cmd_w(CMD, "t"), "Cmd+T must NOT match");
        assert!(!is_strict_cmd_w(CMD, "q"), "Cmd+Q must NOT match");
        assert!(!is_strict_cmd_w(0, "w"), "Plain 'w' without Cmd must NOT match");
    }
}
```
